mapper.select:
SELECT d.`id` 'area.id', d.`name` 'area.name', a.id, a.NAME, a.serial_number, a.specification, a.length, a.material, a.net_weight, a.net_weight*a.quantity total_net_weight, a.gross_weight, a.gross_weight*a.quantity total_gross_weight, a.quantity, a.drawing_number, ifnull(t.taskQuantity,0) taskQuantity, ifnull(t.taskQuantity * a.net_weight,0) taskMete, ifnull(wi.inboundQuantity,0) inboundQuantity, ifnull(wi.inboundQuantity * a.net_weight,0) inboundMete, ifnull(wo.outboundQuantity,0) outboundQuantity, ifnull(wo.outboundQuantity * a.net_weight,0) outboundMete, ifnull(wi.inboundQuantity,0) - ifnull(wo.outboundQuantity,0) stockQuantity, (ifnull(wi.inboundQuantity,0) - ifnull(wo.outboundQuantity,0)) * a.net_weight stockMete, CASE WHEN taskQuantity = inboundQuantity THEN 4 WHEN IFNULL(inboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > inboundQuantity THEN 2 ELSE 0 END status FROM tech_artifact a inner join plan_area d on d.id = a.area_id and d.bool_delete_enum = 0 inner JOIN ( SELECT product_id, SUM( task_quantity ) taskQuantity FROM mes_building_task WHERE task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
AND factory_id = #{factoryId}
GROUP BY product_id ) t ON t.product_id = a.id left join ( select product_id,sum(quantity) inboundQuantity from mes_building_warehouse_summary where product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and type = 1 and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
and factory_id = #{factoryId}
group by product_id ) wi on wi.product_id = a.id left join ( select product_id,sum(quantity) outboundQuantity from mes_building_warehouse_summary where product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and type = 2 and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
and factory_id = #{factoryId}
group by product_id ) wo on wo.product_id = a.id
and a.bool_delete_enum = 0
and a.project_id =#{projectId}
AND a.monomer_id =#{monomerId}
AND a.area_id =#{areaId}
and a.name like CONCAT('%',#{name},'%')
and a.serial_number like CONCAT('%',#{serialNumber},'%')
and a.specification like CONCAT('%',#{specification},'%')
and a.material like CONCAT('%',#{material},'%')
AND taskQuantity > 0
AND ( CASE WHEN taskQuantity = inboundQuantity THEN 4 WHEN IFNULL(inboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > inboundQuantity THEN 2 ELSE 0 END ) = #{status}
AND ( CASE WHEN taskQuantity = outboundQuantity THEN 4 WHEN IFNULL(outboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > outboundQuantity THEN 2 ELSE 0 END ) = #{status}
ORDER BY status DESC,a.serial_number

SELECT d.`id` 'area.id', d.`name` 'area.name', a.id, a.category, a.NAME, a.serial_number, a.plate, a.color, a.thickness, a.width, a.length, a.length * a.width surface_area, a.quantity, ifnull(a.length * a.quantity / 1000,0) totalLength, ifnull(t.taskQuantity,0) taskQuantity, ifnull(t.taskQuantity * a.length,0) taskMete, ifnull(wi.inboundQuantity,0) inboundQuantity, ifnull(wi.inboundQuantity * a.length,0) inboundMete, ifnull(wo.outboundQuantity,0) outboundQuantity, ifnull(wo.outboundQuantity * a.length,0) outboundMete, ifnull(wi.inboundQuantity,0) - ifnull(wo.outboundQuantity,0) stockQuantity, (ifnull(wi.inboundQuantity,0) - ifnull(wo.outboundQuantity,0)) * a.length stockMete, CASE WHEN taskQuantity = inboundQuantity THEN 4 WHEN IFNULL(inboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > inboundQuantity THEN 2 ELSE 0 END status FROM tech_enclosure a inner join plan_area d on d.id = a.area_id and d.bool_delete_enum = 0 inner JOIN ( SELECT product_id, SUM( task_quantity ) taskQuantity FROM mes_building_task WHERE product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
AND factory_id = #{factoryId}
GROUP BY product_id ) t ON t.product_id = a.id left join ( select product_id,sum(quantity) inboundQuantity from mes_building_warehouse_summary where product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and type = 1 and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
and factory_id = #{factoryId}
group by product_id ) wi on wi.product_id = a.id left join ( select product_id,sum(quantity) outboundQuantity from mes_building_warehouse_summary where product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and type = 2 and bool_delete_enum = 0
and monomer_id = #{monomerId}
and area_id = #{areaId}
and factory_id = #{factoryId}
group by product_id ) wo on wo.product_id = a.id
and a.bool_delete_enum = 0
and a.project_id =#{projectId}
AND a.monomer_id =#{monomerId}
AND a.area_id =#{areaId}
and a.category = #{category}
and a.name like CONCAT('%',#{name},'%')
and a.serial_number like CONCAT('%',#{serialNumber},'%')
and a.plate like CONCAT('%',#{plate},'%')
and a.color like CONCAT('%',#{color},'%')
AND taskQuantity > 0
AND ( CASE WHEN taskQuantity = inboundQuantity THEN 4 WHEN IFNULL(inboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > inboundQuantity THEN 2 ELSE 0 END ) = #{status}
AND ( CASE WHEN taskQuantity = outboundQuantity THEN 4 WHEN IFNULL(outboundQuantity,0) = 0 THEN 1 WHEN taskQuantity > outboundQuantity THEN 2 ELSE 0 END ) = #{status}
ORDER BY status DESC,a.serial_number

SELECT *
FROM mes_building_warehouse_summary
where factory_id = #{factoryId}
  AND area_id = #{areaId}
  AND product_id = #{productId}
  AND product_type = #{productType}
  AND quantity > (cargo_quantity + package_quantity)
  AND type = 0
ORDER BY id

SELECT a.id, a.factory_id, a.package_quantity + a.cargo_quantity package_quantity, (CASE cp.bool_required_warehouse when 0 then a.quantity else IFNULL(sum(wsp.quantity), 0) END) AS in_quantity, (CASE cp.bool_required_warehouse WHEN 0 THEN a.quantity - a.package_quantity - a.cargo_quantity ELSE IFNULL(sum(wsp.quantity), 0) - a.package_quantity - a.cargo_quantity END) un_package_quantity, a.product_type, b.project_id, b.monomer_id, b.area_id, b.name, b.serial_number, b.specification, a.product_id, a.warehouse_type, b.length, b.material, b.quantity, b.net_weight, b.total_net_weight, b.gross_weight, b.total_gross_weight, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`id` 'monomer.id', pm.`name` 'monomer.name', pd.`id` 'area.id', pd.`name` 'area.name', mbf.`id` 'factory.id', mbf.`name` 'factory.name', mbw.id AS 'workshopInf.id', mbw.name AS 'workshopInf.name', mbw.id AS 'workshop.id', mbw.name AS 'workshop.name' FROM mes_building_warehouse_summary a LEFT JOIN tech_artifact b ON a.product_id = b.id AND b.bool_delete_enum = FALSE LEFT JOIN contract_project cp ON b.project_id = cp.id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON b.monomer_id = pm.id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON b.area_id = pd.id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON a.factory_id = mbf.id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id LEFT JOIN mes_building_warehouse_storage_product AS wsp ON wsp.warehouse_summary_id = a.id and wsp.product_id = a.product_id AND wsp.bool_delete_enum = 0
a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} AND a.type = 1 AND b.bool_all_part_send_directly = 0 AND a.quantity > a.package_quantity + a.cargo_quantity and b.bool_abnormal_enum = 0 and a.bool_delete_enum = 0
AND b.project_id=#{projectId}
AND b.monomer_id=#{monomerId}
AND b.area_id=#{areaId}
AND b.area_batch_id=#{areaBatchId}
AND a.factory_id=#{factoryId}
and b.name like CONCAT('%',#{name},'%')
and b.serial_number like CONCAT('%',#{serialNumber},'%')
and b.specification like CONCAT('%',#{specification},'%')
and b.material like CONCAT('%',#{material},'%')
AND a.workshop_id=#{workshopId}
AND b.length >= #{minLength}
AND b.length <= #{maxLength}
AND a.warehouse_type in (0,1)
AND a.warehouse_type = 2
GROUP BY a.id HAVING un_package_quantity > 0 ORDER BY a.id DESC

SELECT a.id, a.factory_id, a.package_quantity + a.cargo_quantity package_quantity, a.quantity inquantity, a.quantity - a.package_quantity - a.cargo_quantity un_package_quantity, a.product_type, b.project_id, b.bool_status_enum, b.category, b.name, b.serial_number, b.plate, b.color, b.material, b.weight, b.thickness, b.width, b.length, b.quantity, b.total_length, b.total_area, b.surface_area, b.brand, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pd.`id` 'area.id', pd.`name` 'area.name', mbf.`id` 'factory.id', mbf.`name` 'factory.name', mbw.id 'workshop.id', mbw.name 'workshop.name' FROM mes_building_warehouse_summary a LEFT JOIN tech_enclosure b ON a.product_id = b.id AND b.bool_delete_enum = FALSE and b.bool_abnormal_enum = 0 LEFT JOIN contract_project cp ON b.project_id = cp.id AND cp.bool_delete_enum = FALSE LEFT JOIN enclosure_plan pd ON b.enclosure_plan_id = pd.id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON a.factory_id = mbf.id LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id and mbw.type = 4 AND mbf.bool_delete_enum = FALSE
a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} AND a.type = 1 AND a.quantity > a.package_quantity + a.cargo_quantity and b.bool_abnormal_enum = 0
AND b.project_id=#{projectId}
AND b.enclosure_plan_id = #{areaId}
AND a.factory_id=#{factoryId}
AND b.name like CONCAT('%',#{name},'%')
AND b.serial_number like CONCAT('%',#{serialNumber},'%')
AND b.plate like CONCAT('%',#{plate},'%')
AND b.color like CONCAT('%',#{color},'%')
and b.category = #{category}
AND b.length >= #{minLength}
AND b.length <= #{maxLength}
AND a.warehouse_type in (0,1)
AND a.warehouse_type = 2

SELECT a.id, a.package_quantity + a.cargo_quantity package_quantity, a.quantity inquantity, a.quantity - a.package_quantity - a.cargo_quantity un_package_quantity, a.product_type, b.id AS product_id, b.specification, b.name, b.measure_unit, b.quantity + IFNULL(part.quantity,0) quantity, IFNULL(b.mete, 0) + IFNULL(part.mete,0) mete, b.accounting_unit, b.remark, b.user_id, b.use_property, b.business_id, b.print_quantity, b.print_time, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', sysUser.name AS createUserName, b.classify_name FROM mes_building_warehouse_summary a LEFT JOIN tech_standard_part b ON a.product_id = b.id AND b.bool_delete_enum = FALSE LEFT JOIN tech_standard_part part ON b.original_id = part.id AND part.bool_delete_enum = FALSE and b.original_id is not null LEFT JOIN contract_project cp ON b.project_id = cp.id AND cp.bool_delete_enum = FALSE LEFT JOIN sys_user sysUser ON b.user_id = sysUser.id
a.product_type = 8 AND a.type = 1 AND a.quantity > a.package_quantity + a.cargo_quantity and a.bool_delete_enum = 0
AND a.warehouse_type in (0,1)
AND a.warehouse_type = 2
AND b.project_id=#{projectId}
AND b.monomer_id=#{monomerId}
AND b.area_id=#{areaId}
AND b.name like CONCAT('%',#{name},'%')
AND b.classify_name like CONCAT('%',#{classifyName},'%')
AND b.specification like CONCAT('%',#{specification},'%')
AND b.use_property=#{useProperty}
AND sysUser.name like CONCAT('%',#{createUserName},'%')

SELECT
IFNULL(SUM(wr.quantity),0) quantity,

    
        IFNULL(SUM(a.net_weight * wr.quantity),0) mete
        FROM mes_building_warehouse_summary wr
        INNER JOIN tech_artifact a ON a.id = wr.product_id AND wr.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
    
    
        IFNULL(SUM(e.length * wr.quantity),0) mete
        FROM mes_building_warehouse_summary wr
        INNER JOIN tech_enclosure e ON e.id = wr.product_id AND wr.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
    


    and wr.bool_delete_enum = 0
    
        and wr.project_id = #{projectId}
    
    
        AND wr.monomer_id = #{monomerId}
    
    
        AND wr.factory_id = #{factoryId}
    
    
        AND wr.type = #{type}

SELECT wr.project_id, e.category, IFNULL(SUM(wr.quantity),0) quantity, IFNULL(SUM(e.length * wr.quantity),0) mete FROM mes_building_warehouse_summary wr INNER JOIN tech_enclosure e ON e.id = wr.product_id AND wr.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
and wr.bool_delete_enum = 0 and wr.type = 1
and wr.project_id = #{projectId}
group by wr.project_id,e.category

SELECT wr.product_id, wr.number, wr.factory_id 'factory.id', wr.workshop_id 'workshop.id', wr.warehouse_type, cp.bool_required_warehouse FROM mes_building_warehouse_record AS wr INNER JOIN contract_project AS cp ON wr.project_id = cp.id LEFT JOIN mes_building_warehouse_storage_product AS wsp ON wsp.warehouse_record_id = wr.id AND wsp.bool_delete_enum = 0 WHERE wr.number IS NOT NULL AND wr.bool_delete_enum = 0 AND wr.product_type = 2 AND wr.`status`= 1 AND wr.type = 1 AND cp.bool_delete_enum = 0
AND wr.factory_id = #{factoryId}
AND wr.product_id in
#{productId}
GROUP BY wr.id HAVING (bool_required_warehouse = 0 OR IFNULL(SUM(wsp.quantity), 0) > 0) ORDER BY wr.number ASC

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.contractNo', IFNULL(iTime.inboundQuantity,0) inboundQuantity, IFNULL(iTime.inboundTotalLength,0) inboundTotalLength, IFNULL(iTime.inboundTotalSurfaceArea,0) inboundTotalSurfaceArea, IFNULL(oTime.outboundQuantity,0) outboundQuantity, IFNULL(oTime.outboundTotalLength,0) outboundTotalLength, IFNULL(oTime.outboundTotalSurfaceArea,0) outboundTotalSurfaceArea, IFNULL(a.quantity,0) quantity, IFNULL(a.totalLength,0) totalLength, IFNULL(a.totalSurfaceArea,0) totalSurfaceArea, IFNULL(i.inboundQuantity,0) - IFNULL(o.outboundQuantity,0) stockQuantity, IFNULL(i.inboundTotalLength,0) - IFNULL(o.outboundTotalLength,0) stockTotalLength, IFNULL(i.inboundTotalSurfaceArea,0) - IFNULL(o.outboundTotalSurfaceArea,0) stockTotalSurfaceArea, IFNULL(i.inboundQuantity,0) - IFNULL(o.outboundQuantity,0) - IFNULL(iTime.inboundQuantity,0) + IFNULL(oTime.outboundQuantity,0) beginningQuantity, IFNULL(i.inboundTotalLength,0) - IFNULL(o.outboundTotalLength,0) - IFNULL(iTime.inboundTotalLength,0) + IFNULL(oTime.outboundTotalLength,0) beginningTotalLength, IFNULL(i.inboundTotalSurfaceArea,0) - IFNULL(o.outboundTotalSurfaceArea,0) - IFNULL(iTime.inboundTotalSurfaceArea,0) + IFNULL(oTime.outboundTotalSurfaceArea,0) beginningTotalSurfaceArea FROM contract_project cp LEFT JOIN ( SELECT s.project_id, sum(s.quantity ) inboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) inboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) inboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.category = #{category}
WHERE s.product_type = #{productType} AND s.type = 1 AND s.bool_delete_enum = 0
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
AND DATE_FORMAT(s.create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY s.project_id ) i ON i.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) outboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) outboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) outboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.category = #{category}
WHERE s.product_type = #{productType} AND s.type = 2 AND s.bool_delete_enum = 0
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
AND DATE_FORMAT( s.create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY s.project_id ) o ON o.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) inboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) inboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) inboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.category = #{category}
WHERE s.product_type = #{productType} AND s.type = 1 AND s.bool_delete_enum = 0
AND DATE_FORMAT( s.create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
GROUP BY s.project_id ) iTime ON iTime.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) outboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) outboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) outboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.category = #{category}
WHERE s.product_type = #{productType} AND s.type = 2 AND s.bool_delete_enum = 0
AND DATE_FORMAT( s.create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
GROUP BY s.project_id ) oTime ON oTime.project_id = cp.id LEFT JOIN ( SELECT project_id, sum( quantity ) quantity, IFNULL(SUM(quantity * length), 0 ) totalLength, IFNULL(SUM(quantity * surface_area), 0 ) totalSurfaceArea FROM tech_enclosure WHERE bool_delete_enum = 0
AND category = #{category}
AND project_id = #{projectId}
GROUP BY project_id ) a ON a.project_id = cp.id WHERE cp.bool_delete_enum = 0 AND cp.project_type in (1,2,8)
AND cp.id = #{projectId}
AND cp.name like CONCAT('%', #{projectName},'%')
and cp.id in
#{item}

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.contractNo', IFNULL(iTime.inboundQuantity,0) inboundQuantity, IFNULL(iTime.inboundTotalLength,0) inboundTotalLength, IFNULL(iTime.inboundTotalSurfaceArea,0) inboundTotalSurfaceArea, IFNULL(oTime.outboundQuantity,0) outboundQuantity, IFNULL(oTime.outboundTotalLength,0) outboundTotalLength, IFNULL(oTime.outboundTotalSurfaceArea,0) outboundTotalSurfaceArea, IFNULL(a.quantity,0) quantity, IFNULL(a.totalLength,0) totalLength, IFNULL(a.totalSurfaceArea,0) totalSurfaceArea, IFNULL(i.inboundQuantity,0) - IFNULL(o.outboundQuantity,0) stockQuantity, IFNULL(i.inboundTotalLength,0) - IFNULL(o.outboundTotalLength,0) stockTotalLength, IFNULL(i.inboundTotalSurfaceArea,0) - IFNULL(o.outboundTotalSurfaceArea,0) stockTotalSurfaceArea, IFNULL(i.inboundQuantity,0) - IFNULL(o.outboundQuantity,0) - IFNULL(iTime.inboundQuantity,0) + IFNULL(oTime.outboundQuantity,0) beginningQuantity, IFNULL(i.inboundTotalLength,0) - IFNULL(o.outboundTotalLength,0) - IFNULL(iTime.inboundTotalLength,0) + IFNULL(oTime.outboundTotalLength,0) beginningTotalLength, IFNULL(i.inboundTotalSurfaceArea,0) - IFNULL(o.outboundTotalSurfaceArea,0) - IFNULL(iTime.inboundTotalSurfaceArea,0) + IFNULL(oTime.outboundTotalSurfaceArea,0) beginningTotalSurfaceArea FROM contract_project cp LEFT JOIN ( SELECT s.project_id, sum(s.quantity ) inboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) inboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) inboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.dictionary_id = #{dictionaryId}
WHERE s.product_type = #{productType} AND s.type = 1 AND s.bool_delete_enum = 0
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
AND DATE_FORMAT(s.create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY s.project_id ) i ON i.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) outboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) outboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) outboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.dictionary_id = #{dictionaryId}
WHERE s.product_type = #{productType} AND s.type = 2 AND s.bool_delete_enum = 0
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
AND DATE_FORMAT( s.create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY s.project_id ) o ON o.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) inboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) inboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) inboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.dictionary_id = #{dictionaryId}
WHERE s.product_type = #{productType} AND s.type = 1 AND s.bool_delete_enum = 0
AND DATE_FORMAT( s.create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
GROUP BY s.project_id ) iTime ON iTime.project_id = cp.id LEFT JOIN ( SELECT s.project_id, sum( s.quantity ) outboundQuantity, IFNULL(SUM(s.quantity * ta.length), 0 ) outboundTotalLength, IFNULL(SUM(s.quantity * ta.surface_area), 0 ) outboundTotalSurfaceArea FROM mes_building_warehouse_record s INNER JOIN tech_enclosure ta ON ta.id = s.product_id
AND ta.dictionary_id = #{dictionaryId}
WHERE s.product_type = #{productType} AND s.type = 2 AND s.bool_delete_enum = 0
AND DATE_FORMAT( s.create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND s.project_id = #{projectId}
AND s.workshop_id = #{workShopId}
GROUP BY s.project_id ) oTime ON oTime.project_id = cp.id LEFT JOIN ( SELECT project_id, sum( quantity ) quantity, IFNULL(SUM(quantity * length), 0 ) totalLength, IFNULL(SUM(quantity * surface_area), 0 ) totalSurfaceArea FROM tech_enclosure WHERE bool_delete_enum = 0
AND dictionary_id = #{dictionaryId}
AND project_id = #{projectId}
GROUP BY project_id ) a ON a.project_id = cp.id WHERE cp.bool_delete_enum = 0 AND cp.project_type in (1,2,8)
AND cp.id = #{projectId}
AND cp.name like CONCAT('%', #{projectName},'%')
and cp.id in
#{item}

SELECT pm.`name` monomerName, pa.`name` areaName,
a.`name` name, '构件' AS typeName,
a.`name` name, CASE when a.bool_all_part_send_directly = '0' then '直发件' else '直发檩条' END typeName,
a.serial_number serialNumber, a.specification specification, a.length length, a.bool_all_part_send_directly, IFNULL( a.quantity, 0 ) quantity, IFNULL( a.quantity * a.net_weight, 0 ) totalNetWeight, IFNULL( i.inboundQuantity, 0 ) inboundQuantity, IFNULL( i.inboundQuantity * a.net_weight, 0 ) inboundNetWeight, IFNULL( o.outboundQuantity, 0 ) outboundQuantity, IFNULL( o.outboundQuantity * a.net_weight, 0 ) outboundNetWeight, IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 ) AS stockQuantity, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 )) * a.net_weight AS stockNetWeight, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 ))-( IFNULL( otime.outboundQuantity, 0 ) - IFNULL( o.outboundQuantity, 0 )) AS beginningQuantity, ((IFNULL( itime.inboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 ))-( IFNULL( otime.outboundQuantity, 0 ) - IFNULL( o.outboundQuantity, 0 ))) * a.net_weight AS beginningNetWeight, IFNULL( a.quantity * a.gross_weight, 0 ) totalGrossWeight, IFNULL( i.inboundQuantity * a.gross_weight, 0 ) inboundGrossWeight, IFNULL( o.outboundQuantity * a.gross_weight, 0 ) outboundGrossWeight, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 )) * a.gross_weight AS stockGrossWeight, ((IFNULL( itime.inboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 ))-( IFNULL( otime.outboundQuantity, 0 ) - IFNULL( o.outboundQuantity, 0 ))) * a.gross_weight AS beginningGrossWeight, IFNULL( package.packageQuantity, 0 ) packageQuantity, IFNULL( package.packageQuantity * a.net_weight, 0 ) packageNetWeight, IFNULL( package.packageQuantity * a.gross_weight, 0 ) packageGrossWeight
FROM
tech_artifact a
tech_machine_part a
tech_assemble a
LEFT JOIN ( SELECT product_id, sum( quantity ) inboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND type = 1 AND warehouse_type in(0,2)
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
AND date_format(create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY product_id ) i ON i.product_id = a.id LEFT JOIN ( SELECT product_id, sum( quantity ) outboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND warehouse_type in(0,2) AND type = 2
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
AND date_format(create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY product_id ) o ON o.product_id = a.id
LEFT JOIN ( SELECT product_id, sum( quantity ) inboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND warehouse_type in(0,2) AND type = 1
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY product_id ) itime ON itime.product_id = a.id LEFT JOIN ( SELECT product_id, sum( quantity ) outboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND warehouse_type in(0,2) AND type = 2
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY product_id ) otime ON otime.product_id = a.id LEFT JOIN ( SELECT product_id, sum( quantity ) packageQuantity FROM mes_building_package_link WHERE bool_delete_enum = 0 AND product_type = #{productType} AND warehouse_type in(0,2)
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
AND date_format(create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY product_id ) package ON package.product_id = a.id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id WHERE a.bool_delete_enum = 0
and a.bool_all_part_send_directly = 0
and a.bool_send_directly = 1
and a.relation_type !=18
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.serial_number like CONCAT('%',#{serialNumber},'%')

SELECT pa.`name` enclosurePlanName, a.serial_number serialNumber, a.plate, a.category, a.length, a.surface_area, IFNULL( a.quantity, 0 ) quantity, IFNULL( a.quantity * a.length, 0 ) totalLength, IFNULL( a.quantity * a.surface_area, 0 ) totalSurfaceArea, IFNULL( i.inboundQuantity, 0 ) inboundQuantity, IFNULL( i.inboundQuantity * a.length, 0 ) inboundTotalLength, IFNULL( i.inboundQuantity * a.surface_area, 0 ) inboundTotalSurfaceArea, IFNULL( o.outboundQuantity, 0 ) outboundQuantity, IFNULL( o.outboundQuantity * a.length, 0 ) outboundTotalLength, IFNULL( o.outboundQuantity * a.surface_area, 0 ) outboundTotalSurfaceArea, IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 ) AS stockQuantity, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 )) * a.length AS stockTotalLength, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 )) * a.surface_area AS stockTotalSurfaceArea, IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 ) + IFNULL( o.outboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 ) AS beginningQuantity, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 ) + IFNULL( o.outboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 )) * a.length AS beginningTotalLength, (IFNULL( itime.inboundQuantity, 0 ) - IFNULL( otime.outboundQuantity, 0 ) + IFNULL( o.outboundQuantity, 0 ) - IFNULL( i.inboundQuantity, 0 )) * a.surface_area AS beginningSurfaceArea FROM tech_enclosure a LEFT JOIN ( SELECT product_id, sum( quantity ) inboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND type = 1
AND project_id = #{projectId}
AND plan_id = #{enclosurePlanId}
AND workshop_id = #{workshopId}
AND DATE_FORMAT(create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY product_id ) i ON i.product_id = a.id LEFT JOIN ( SELECT product_id, sum( quantity ) outboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND type = 2
AND project_id = #{projectId}
AND plan_id = #{enclosurePlanId}
AND workshop_id = #{workshopId}
AND DATE_FORMAT(create_time, '%Y-%m' )= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY product_id ) o ON o.product_id = a.id
LEFT JOIN ( SELECT product_id, sum( quantity ) inboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND type = 1
AND project_id = #{projectId}
AND plan_id = #{enclosurePlanId}
AND workshop_id = #{workshopId}
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY product_id ) itime ON itime.product_id = a.id LEFT JOIN ( SELECT product_id, sum( quantity ) outboundQuantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND product_type = #{productType} AND type = 2
AND project_id = #{projectId}
AND plan_id = #{enclosurePlanId}
AND workshop_id = #{workshopId}
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
GROUP BY product_id ) otime ON otime.product_id = a.id LEFT JOIN enclosure_plan pa ON a.enclosure_plan_id = pa.id AND pa.bool_delete_enum = FALSE WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.enclosure_plan_id = #{enclosurePlanId}
AND a.category = #{category}
AND a.serial_number like CONCAT('%',#{serialNumber},'%')

select a.* FROM (
SELECT a.id, a.factory_id, a.package_quantity + a.cargo_quantity package_quantity, a.quantity inquantity, a.quantity - a.package_quantity - a.cargo_quantity un_package_quantity, a.product_type, b.project_id, b.monomer_id, b.area_id, b.serial_number, b.specification, a.product_id, b.length, b.material, b.quantity, b.net_weight, b.total_net_weight, b.bool_all_part_send_directly, b.name, b.remark, ifnull(b.gross_weight,0) gross_weight, ifnull(b.total_gross_weight,0) total_gross_weight, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`id` 'monomer.id', pm.`name` 'monomer.name', pd.`id` 'area.id', pd.`name` 'area.name', mbf.`id` 'factory.id', mbf.`name` 'factory.name', mbw.id 'workshop.id', mbw.name 'workshop.name' FROM mes_building_warehouse_summary a
LEFT JOIN tech_machine_part b ON a.product_id = b.id AND b.bool_delete_enum =FALSE AND b.relation_type in (2,16)
LEFT JOIN tech_assemble b ON a.product_id = b.id AND b.bool_delete_enum =FALSE
LEFT JOIN contract_project cp ON b.project_id = cp.id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON b.monomer_id = pm.id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON b.area_id = pd.id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON a.factory_id = mbf.id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = a.workshop_id
a.product_type = #{productType} AND a.type = 1 and a.bool_delete_enum = 0 AND a.quantity > a.package_quantity + a.cargo_quantity and b.bool_send_directly = 1
AND b.project_id=#{projectId}
AND b.monomer_id=#{monomerId}
AND b.area_id=#{areaId}
AND b.area_batch_id=#{areaBatchId}
AND a.factory_id=#{factoryId}
and b.name like CONCAT('%',#{name},'%')
and b.serial_number like CONCAT('%',#{serialNumber},'%')
and b.specification like CONCAT('%',#{specification},'%')
and b.material like CONCAT('%',#{material},'%')
AND a.workshop_id=#{workshopId}
AND b.length >= #{minLength}
AND b.length <= #{maxLength}
) a

SELECT IFNULL( SUM(record.quantity), 0 ), IFNULL( SUM(record.quantity * product.net_weight), 0 ) net_weight, IFNULL( SUM(record.quantity * product.gross_weight), 0 ) gross_weight FROM mes_building_warehouse_record record LEFT JOIN tech_artifact product ON record.product_id = product.id WHERE record.bool_delete_enum=0
AND record.project_id=#{projectId}
AND record.workshop_id=#{workshopId}
AND DATE(record.create_time)>=DATE(#{startDate})
AND DATE(record.create_time)<=DATE(#{endDate})
AND record.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} AND record.type=1

select ifnull(sum(a.quantity * b.net_weight) / 1000,0 ) as ton from mes_building_warehouse_summary a left join tech_artifact b on b.bool_delete_enum = 0 and a.product_id = b.id where a.bool_delete_enum = 0 and a.product_type = 2 and a.type = #{type}
and a.project_id = #{projectId}
and DATE_SUB( CURDATE(), INTERVAL 30 DAY ) <= date( a.create_time )

select a.dateValue `key`, ifnull( b.ton, 0 ) `val`, ifnull( c.carCount, 0 ) `val2` from ( SELECT DATE_FORMAT( CURDATE( ), '%Y-%m' ) AS dateValue UNION SELECT DATE_FORMAT( ( CURDATE( ) - INTERVAL 1 MONTH ), '%Y-%m' ) AS dateValue UNION SELECT DATE_FORMAT( ( CURDATE( ) - INTERVAL 2 MONTH ), '%Y-%m' ) AS dateValue UNION SELECT DATE_FORMAT( ( CURDATE( ) - INTERVAL 3 MONTH ), '%Y-%m' ) AS dateValue UNION SELECT DATE_FORMAT( ( CURDATE( ) - INTERVAL 4 MONTH ), '%Y-%m' ) AS dateValue UNION SELECT DATE_FORMAT( ( CURDATE( ) - INTERVAL 5 MONTH ), '%Y-%m' ) AS dateValue ) a left join ( select a.dateValue, sum( a.total_weight ) ton from ( select date_format( a.create_time, '%Y-%m' ) as dateValue, ifnull( ( a.quantity * b.net_weight ) / 1000, 0 ) as total_weight from mes_building_warehouse_summary a left join tech_artifact b on b.bool_delete_enum = 0 and a.product_id = b.id where a.bool_delete_enum = 0 and a.product_type = 2 and a.type = 2 ) a group by a.dateValue ) b on a.dateValue = b.dateValue left join ( select a.dateValue, count( 1 ) carCount from ( select date_format( a.create_time, '%Y-%m' ) dateValue from mes_building_cargo_list a where a.bool_delete_enum = 0 and a.`status` = 4
and a.project_id = #{projectId}
) a GROUP BY a.dateValue ) c on a.dateValue = c.dateValue order by a.dateValue

select ifnull( sum(a.quantity) , 0) as quantity from mes_building_warehouse_summary a left join tech_artifact b on b.bool_delete_enum = 0 and a.product_id = b.id where a.bool_delete_enum = 0 and a.product_type = 2 and a.type = #{type}
and a.project_id = #{projectId}
and DATE_SUB( CURDATE(), INTERVAL 30 DAY ) <= date( a.create_time )

SELECT pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.id product_id, a.quantity, a.serial_number, a.name, a.specification, a.material, a.net_weight, a.total_net_weight, a.gross_weight, a.total_gross_weight FROM (SELECT record.monomer_id, record.area_id, product.id, product.`name`, product.serial_number, product.specification, product.material, product.net_weight, product.gross_weight, IFNULL( SUM(record.quantity), 0 ) quantity, IFNULL( SUM(record.quantity * product.net_weight), 0 ) total_net_weight, IFNULL( SUM(record.quantity * product.gross_weight), 0 ) total_gross_weight FROM mes_building_warehouse_record record LEFT JOIN tech_artifact product ON record.product_id = product.id WHERE record.bool_delete_enum=0
AND record.project_id=#{projectId}
AND record.workshop_id=#{workshopId}
AND record.monomer_id=#{monomerId}
AND record.area_id=#{areaId}
product.serial_number like CONCAT('%',#{serialNumber},'%')
AND DATE(record.create_time)>=DATE(#{startDate})
AND DATE(record.create_time)<=DATE(#{endDate})
AND record.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} AND record.type=1 GROUP BY record.monomer_id, record.area_id, product.id) a LEFT JOIN plan_area pa ON a.area_id = pa.id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id

SELECT summary.product_id groupKey, summary.quantity - IFNULL( a.quantity, 0 ) - IFNULL( b.quantity, 0 ) mete FROM mes_building_warehouse_summary summary LEFT JOIN ( SELECT link.product_id, summary.workshop_id workshop_id, sum( link.quantity ) quantity FROM mes_building_cargo_list_product_link link LEFT JOIN mes_building_warehouse_summary summary ON link.warehouse_record_id = summary.id AND summary.bool_delete_enum = 0 LEFT JOIN mes_building_cargo_list list ON link.cargo_list_id = list.id WHERE link.bool_delete_enum = 0 AND link.product_type = #{type} AND list.shipment_status > 2 AND list.shipment_status < 2 AND summary.workshop_id=#{workshopId} and link.product_id in
#{item}
GROUP BY link.product_id, summary.workshop_id ) a ON summary.product_id = a.product_id AND summary.workshop_id = a.workshop_id LEFT JOIN ( SELECT plink.product_id product_id , sum( plink.quantity ) quantity FROM mes_building_package_link plink LEFT JOIN mes_building_warehouse_summary summary ON plink.warehouse_record_id = summary.id AND summary.bool_delete_enum = 0 WHERE plink.bool_delete_enum = 0 AND plink.product_type = #{type} AND plink.product_id IN
#{item}
AND summary.workshop_id = #{workshopId} GROUP BY plink.product_id )b ON summary.product_id = b.product_id WHERE summary.bool_delete_enum = 0 and summary.product_id in
#{item}
AND summary.product_type = #{type} AND summary.workshop_id=#{workshopId} AND summary.type = 1

select summ.*,a.name from mes_building_warehouse_summary summ left join ( SELECT product_id,en.name from mes_enclosure_task task left join tech_enclosure en on task.product_id = en.id where task.bool_complete_enum = 0 and en.bool_delete_enum = 0 and task.task_order_id = #{orderId} and task.id in
#{taskId}
)a on summ.product_id = a.product_id where summ.bool_delete_enum = 0 and summ.product_type = '8' and summ.type = '1'

select sum.* from mes_building_warehouse_summary sum where sum.bool_delete_enum=0 and sum.product_type in (4,8) and sum.type = #{type}
and sum.project_id in
#{projectId}
union all select sum.* from mes_building_warehouse_summary sum left join tech_machine_part part on sum.product_id = part.id and sum.product_type = 1 where sum.bool_delete_enum=0 and part.bool_send_directly = 1 and part.bool_all_part_send_directly = 1 and sum.type = #{type}
and sum.project_id in
#{projectId}
union all select sum.* from mes_building_warehouse_summary sum left join tech_assemble ass on sum.product_id = ass.id and sum.product_type = 16 where sum.bool_delete_enum=0 and ass.bool_send_directly = 1 and ass.bool_all_part_send_directly = 1 and sum.type = #{type}
and sum.project_id in
#{projectId}
union all select sum.* from mes_building_warehouse_summary sum left join tech_artifact art on sum.product_id = art.id and sum.product_type = 2 where sum.bool_delete_enum=0 and art.bool_all_part_send_directly = 0 and sum.type = #{type}
and sum.project_id in
#{projectId}

select
*
from
mes_building_warehouse_summary
where

    
        ( factory_id= #{addWarehouseDTO.factoryId}
        and workshop_id= #{addWarehouseDTO.workshopId}
        and product_type= #{addWarehouseDTO.productType}
        and product_id= #{addWarehouseDTO.productId}
        and type= #{addWarehouseDTO.type})
    

and bool_delete_enum=0

SELECT sum( a.quantity * b.net_weight ) weights FROM mes_building_warehouse_record a INNER JOIN tech_artifact b ON b.id = a.product_id WHERE a.bool_delete_enum = 0 AND b.bool_delete_enum = 0 AND a.type = 1 AND a.product_type = 2
AND a.workshop_id in
#{workshopId}
AND a.project_id in
#{projectIdOne}
AND a.project_id = #{projectId}
AND DATE_FORMAT(a.create_time,'%Y') = #{year}

SELECT a.id id, t.id whId, a.name name, a.serial_number, a.specification, a.length, a.material, a.drawing_number, a.net_weight, a.gross_weight, a.total_net_weight, a.total_gross_weight, a.quantity, a.bool_all_part_send_directly boolAllPartSendDirectly, a.surface_area, t.quantity AS warehouseQuantity, t.print_quantity, t.print_time, false AS 'boolOneCode', p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', d.`id` 'area.id', d.`name` 'area.name' FROM mes_building_warehouse_summary t INNER JOIN tech_artifact a ON a.id = t.product_id left join contract_project p on p.id = a.project_id left join plan_monomer m on m.id = a.monomer_id left join plan_area d on d.id = a.area_id WHERE t.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} and t.bool_delete_enum = 0 and t.warehouse_type = 2 and t.type= 1
AND t.project_id = #{projectId}
AND t.monomer_id = #{monomerId}
AND t.area_id = #{areaId}
AND a.name LIKE CONCAT('%',#{name},'%')
AND a.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND a.specification LIKE CONCAT('%',#{specification},'%')
AND a.material LIKE CONCAT('%',#{material},'%')

SELECT enc.id productId, enc.id id, task.id whId, enc.*, task.quantity AS warehouseQuantity, pro.id 'project.id', pro.NAME 'project.name', pro.short_name 'project.short_name', pro.serial_number 'project.serial_number', plan.`id` 'plan.id', plan.`name` 'plan.name', task.bool_printed 'boolPrinted' FROM mes_building_warehouse_summary task LEFT JOIN tech_enclosure enc ON task.product_id = enc.id AND enc.bool_delete_enum = 0 LEFT JOIN contract_project pro ON pro.id = enc.project_id AND pro.bool_delete_enum = 0 LEFT JOIN enclosure_plan plan ON plan.id = enc.enclosure_plan_id AND plan.bool_delete_enum = 0 WHERE task.bool_delete_enum =0 and task.warehouse_type = 2 and task.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} and task.type = 1
AND task.plan_id = #{planId}
AND task.project_id = #{projectId}
AND task.category = #{category}
AND enc.name LIKE CONCAT('%',#{name},'%')
AND enc.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND enc.specification LIKE CONCAT('%',#{specification},'%')
AND enc.material LIKE CONCAT('%',#{material},'%')

SELECT y_t.`year` as `groupKey`, IFNULL(temp1.mete, 0) as mete FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year`
) y_t LEFT JOIN ( SELECT DATE_FORMAT(a.create_time, "%Y-%m") as `dateTime`, IFNULL(sum(a.quantity * b.net_weight ),0) mete FROM mes_building_warehouse_summary a INNER JOIN tech_artifact b ON a.product_id = b.id and b.bool_delete_enum = 0 WHERE a.product_type = 2 AND a.type =2 and a.warehouse_type in (0,2) and a.bool_delete_enum = 0
AND DATE_FORMAT(a.create_time, '%Y' ) = DATE_FORMAT(#{yearDate}, '%Y')
AND a.workshop_id = #{workshopId}
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = a.project_id )
AND a.workshop_id = #{workshopId}
group by DATE_FORMAT(a.create_time, "%Y-%m") ) AS temp1 ON temp1.dateTime = y_t.`year`

SELECT y_t.`year` as `groupKey`, IFNULL(temp1.mete, 0) as mete FROM (
select DATE_FORMAT(#{i}, '%Y') as `year`
) y_t LEFT JOIN ( SELECT DATE_FORMAT(a.create_time, "%Y") as `dateTime`, IFNULL(sum(a.quantity * b.net_weight ),0) mete FROM mes_building_warehouse_summary a INNER JOIN tech_artifact b ON a.product_id = b.id and b.bool_delete_enum = 0 WHERE a.product_type = 2 AND a.type =2 and a.warehouse_type in (0,2) and a.bool_delete_enum = 0
AND a.workshop_id = #{workshopId}
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = a.project_id )
AND a.workshop_id = #{workshopId}
group by DATE_FORMAT(a.create_time, "%Y") ) AS temp1 ON temp1.dateTime = y_t.`year`
